bounded_host_request.command:
set -euo pipefail
docker image inspect create-videobot:poll-candidate >/dev/null 2>&1 || exit 61
docker run --rm --network none --pull never --entrypoint /bin/sh create-videobot:poll-candidate -c '
test -f /opt/videobot/src/runtime/creatorPollingMain.mjs || exit 80
test -f /opt/videobot/src/runtime/config.mjs || exit 81
test -f /opt/videobot/src/runtime/creatorPollingConsumer.mjs || exit 82
test -f /opt/videobot/src/runtime/creatorMigrate.mjs || exit 83
test -f /opt/videobot/src/runtime/main.mjs || exit 84
test -d /opt/videobot/node_modules/pg || exit 85
exit 0' || exit $?
docker run --rm --network none --pull never --entrypoint node create-videobot:poll-candidate -e "
import('./src/runtime/creatorPollingMain.mjs').then(()=>process.exit(0)).catch(e=>{
 const m=String(e?.message??'');
 const f=m.match(/Cannot find module '([^']+)'/);
 const file=f?.[1]?.split('/').pop()??'';
 const map={'creatorPollingMain.mjs':90,'config.mjs':91,'creatorPollingConsumer.mjs':92,'creatorMigrate.mjs':93,'main.mjs':94};
 process.exit(map[file]??95);
})"
